const dns = require('dns');
const crypto = require('crypto');
const http = require('http');

const ENCRYPTION_KEY = crypto.randomBytes(32);
const IV_LENGTH = 12; // GCM recommended IV length
const AUTH_TAG_LENGTH = 16;

function encrypt(text) {
  const iv = crypto.randomBytes(IV_LENGTH);
  const cipher = crypto.createCipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  let encrypted = cipher.update(text, 'utf8', 'hex');
  encrypted += cipher.final('hex');
  const authTag = cipher.getAuthTag().toString('hex');
  return iv.toString('hex') + ':' + authTag + ':' + encrypted;
}

function decrypt(text) {
  const parts = text.split(':');
  if (parts.length !== 3) throw new Error('Invalid encrypted data');
  const iv = Buffer.from(parts[0], 'hex');
  if (iv.length !== IV_LENGTH) throw new Error('Invalid IV');
  const authTag = Buffer.from(parts[1], 'hex');
  if (authTag.length !== AUTH_TAG_LENGTH) throw new Error('Invalid auth tag');
  const decipher = crypto.createDecipheriv('aes-256-gcm', ENCRYPTION_KEY, iv);
  decipher.setAuthTag(authTag);
  let decrypted = decipher.update(parts[2], 'hex', 'utf8');
  decrypted += decipher.final('utf8');
  return decrypted;
}

const dnsCache = new Map();

class DNSRecord {
  constructor(hostname, addresses, ttl) {
    this.hostname = hostname;
    this.addresses = addresses;
    this.ttl = ttl;
    this.timestamp = Date.now();
  }

  isExpired() {
    return (Date.now() - this.timestamp) > (this.ttl * 1000);
  }
}

class TemplateEngine {
  constructor() {
    this.helpers = {
      formatDate: (ts) => new Date(ts).toISOString(),
      uppercase: (s) => String(s).toUpperCase(),
      json: (obj) => JSON.stringify(obj, null, 2)
    };
  }

  render(template, context) {
    const safeContext = { ...context, helpers: this.helpers };
    const processed = template.replace(/\{\{([^}]+)\}\}/g, (match, expr) => {
      try {
        const parts = expr.trim().split('.');
        let value = safeContext;
        for (const part of parts) {
          const funcMatch = part.match(/^(\w+)\((\w+)\)$/);
          if (funcMatch && value && typeof value[funcMatch[1]] === 'function') {
            const argName = funcMatch[2];
            const argVal = safeContext[argName] !== undefined ? safeContext[argName] : context[argName];
            value = value[funcMatch[1]](argVal);
          } else if (value && Object.prototype.hasOwnProperty.call(value, part)) {
            value = value[part];
          } else {
            return match;
          }
        }
        return value !== undefined ? String(value) : '';
      } catch (e) {
        return match;
      }
    });
    return processed;
  }
}

const templateEngine = new TemplateEngine();

const RESPONSE_TEMPLATES = {
  success: '<div class="result"><h3>DNS Lookup: {{hostname}}</h3><p>Addresses: {{addresses}}</p><p>TTL: {{ttl}}s</p><p>Cached: {{timestamp}}</p></div>',
  error: '<div class="error"><h3>Lookup Failed</h3><p>Host: {{hostname}}</p><p>Error: {{errorMessage}}</p></div>',
  list: '<div class="cache"><h3>Cached Records</h3><ul>{{entries}}</ul></div>'
};

const ALLOWED_FORMAT_TOKENS = new Set(['hostname', 'addresses', 'ttl', 'timestamp']);

function validateFormat(format) {
  const tokens = format.match(/\{\{([^}]+)\}\}/g) || [];
  for (const token of tokens) {
    const expr = token.slice(2, -2).trim();
    if (!ALLOWED_FORMAT_TOKENS.has(expr)) {
      return false;
    }
  }
  if (format.length > 500) return false;
  return true;
}

function resolveAndCache(hostname, callback) {
  if (dnsCache.has(hostname)) {
    try {
      const encrypted = dnsCache.get(hostname);
      const data = JSON.parse(decrypt(encrypted));
      const record = new DNSRecord(data.hostname, data.addresses, data.ttl);
      record.timestamp = data.timestamp;
      if (!record.isExpired()) {
        return callback(null, record);
      }
    } catch (e) {
      // Decryption failed, remove stale entry
    }
    dnsCache.delete(hostname);
  }

  dns.resolve4(hostname, { ttl: true }, (err, addresses) => {
    if (err) return callback(err, null);
    const ttl = addresses[0] && addresses[0].ttl ? addresses[0].ttl : 300;
    const addrs = addresses.map(a => typeof a === 'object' ? a.address : a);
    const record = new DNSRecord(hostname, addrs, ttl);
    const serialized = JSON.stringify(record);
    dnsCache.set(hostname, encrypt(serialized));
    callback(null, record);
  });
}

function escapeHtml(str) {
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

function buildResponseFromRecord(record) {
  const safeRecord = {
    hostname: escapeHtml(record.hostname),
    addresses: escapeHtml(JSON.stringify(record.addresses)),
    ttl: Number(record.ttl),
    timestamp: escapeHtml(new Date(record.timestamp).toISOString())
  };
  return templateEngine.render(RESPONSE_TEMPLATES.success, safeRecord);
}

function buildErrorResponse(hostname, error) {
  return templateEngine.render(RESPONSE_TEMPLATES.error, {
    hostname: escapeHtml(hostname),
    errorMessage: escapeHtml(error.message || 'Unknown error')
  });
}

function buildCustomResponse(userFormat, record) {
  const safeRecord = {
    hostname: escapeHtml(record.hostname),
    addresses: escapeHtml(JSON.stringify(record.addresses)),
    ttl: Number(record.ttl),
    timestamp: escapeHtml(new Date(record.timestamp).toISOString())
  };
  return templateEngine.render(userFormat, safeRecord);
}

const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);

  if (url.pathname === '/resolve' && req.method === 'GET') {
    const hostname = url.searchParams.get('host');
    const format = url.searchParams.get('format');

    if (!hostname || !/^[a-zA-Z0-9][a-zA-Z0-9.-]+[a-zA-Z]{2,}$/.test(hostname)) {
      res.writeHead(400, { 'Content-Type': 'text/html' });
      res.end('<p>Invalid hostname</p>');
      return;
    }

    resolveAndCache(hostname, (err, record) => {
      res.writeHead(200, { 'Content-Type': 'text/html' });
      if (err) {
        res.end(buildErrorResponse(hostname, err));
      } else if (format && validateFormat(format)) {
        res.end(buildCustomResponse(format, record));
      } else if (format) {
        res.end('<p>Invalid format template</p>');
      } else {
        res.end(buildResponseFromRecord(record));
      }
    });
  } else if (url.pathname === '/cache' && req.method === 'GET') {
    const entries = [];
    for (const [host, encrypted] of dnsCache) {
      try {
        const data = JSON.parse(decrypt(encrypted));
        entries.push(`<li>${escapeHtml(host)}: ${escapeHtml(data.addresses.join(', '))}</li>`);
      } catch (e) {
        entries.push(`<li>${escapeHtml(host)}: [error]</li>`);
      }
    }
    const html = templateEngine.render(RESPONSE_TEMPLATES.list, { entries: entries.join('') });
    res.writeHead(200, { 'Content-Type': 'text/html' });
    res.end(html);
  } else {
    res.writeHead(404);
    res.end('Not Found');
  }
});

server.listen(3000, () => console.log('DNS Resolver running on port 3000'));

module.exports = { server, encrypt, decrypt, templateEngine, resolveAndCache };
